using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;

static class V13WorkflowChecks {
 static T F<T>(object obj,string name){return (T)obj.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(obj);}
 static IEnumerable<Button> Buttons(DependencyObject obj){if(obj is Button)yield return (Button)obj;for(int i=0;i<VisualTreeHelper.GetChildrenCount(obj);i++)foreach(var b in Buttons(VisualTreeHelper.GetChild(obj,i)))yield return b;}
 public static void Run(Application app,string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"flow-state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);AppSettings.Load();GlassTheme.Apply(false,false);var log=new List<string>();Action<bool,string> check=(ok,what)=>{log.Add((ok?"PASS ":"FAIL ")+what);if(!ok)throw new Exception(what);};var main=new MainWindow(true);main.ContentRendered+=async(s,e)=>{try{await Transitions.WhenReady(main);main.PreviewSize(1600,1000);var editor=F<CodeEditor>(main,"editor");string original="#include <stdio.h>\nint main(void)\n{\n    puts(\"original draft\");\n    return 0;\n}\n";string failed="int main(void){return ???;}";editor.Text=original;var problem=Bank.All()[0];MistakeBook.Record(problem,new Evaluation{ProblemId=1,Title=problem.Title,Code=failed,Compiler="answer.c:1: error: expression expected",Score=0,Compiled=false},false);
 var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)};timer.Tick+=(a,b)=>{var book=main.OwnedWindows.Cast<Window>().OfType<MistakeWindow>().FirstOrDefault();if(book==null)return;timer.Stop();Theme.Capture((FrameworkElement)book.Content,Path.Combine(Path.GetDirectoryName(path),"mistake-book-zh.png"));Buttons(book).First(x=>x.Content as string=="恢复失败代码").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};timer.Start();typeof(MainWindow).GetMethod("OpenMistakes",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(main,null);await Task.Delay(350);check(editor.Text==failed,"Mistake-book restore button restores the selected failed code");string backups=Path.Combine(Engine.DataRoot,"mistake-restore-backups");check(Directory.GetFiles(backups,"*.c").Any(f=>File.ReadAllText(f)==original),"Restoring failed code backs up the original draft before replacement");
 editor.Text=original;var pick=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)};pick.Tick+=(a,b)=>{var popup=main.OwnedWindows.Cast<Window>().FirstOrDefault(x=>x.IsVisible&&x.Title=="错误定位");if(popup==null)return;pick.Stop();Buttons(popup).First(x=>x.Content is TextBlock&&((TextBlock)x.Content).Text.Contains("answer.c:4:4")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};pick.Start();PracticeTools.Diagnostics(main,"answer.c:4:4: error: ';' expected",(line,col)=>ErrorLocation.Jump(editor,line,col));await Task.Delay(350);check(editor.Input.TextArea.Caret.Line==4&&editor.Input.TextArea.Caret.Column==4&&editor.Input.IsKeyboardFocusWithin,"Clicking a diagnostic returns editing focus to exactly line 4, column 4 after the dialog closes");
 AppSettings.SetLanguage("en");var custom=new CustomRunWindow("#include <stdio.h>\nint main(void){char s[128];if(scanf(\"%127s\",s)==1)printf(\"%s\",s);return 0;}","输入 原始数据",null,(line,col)=>{}){Owner=main};custom.Show();await Transitions.WhenReady(custom);await custom.Execute();check(F<TextBox>(custom,"output").Text=="输入","Custom output preserves Chinese payload exactly in English mode");Theme.Capture((FrameworkElement)custom.Content,Path.Combine(Path.GetDirectoryName(path),"custom-input-en.png"));custom.Close();await Task.Delay(240);
 var ev=new Evaluation{ProblemId=1,Compiled=true,Code="int main(void){/* 输入 */return 0;}",Title=problem.Title};var test=new CaseResult{Test=new TestCase("输入\n","输入\n",false),Run=new Execution{Output="输入\n"},Passed=true,Diagnosis="输出符合要求"};ev.Cases.Add(test);string report=Engine.Report(ev);check(PracticeTools.CaseText(test).Contains("输入\n")&&report.EndsWith(ev.Code),"English results and exported report preserve raw input/output and submitted source");F<Evaluation>(main,"evaluation");typeof(MainWindow).GetField("evaluation",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(main,ev);typeof(MainWindow).GetMethod("PopulateOutputs",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(main,null);AppSettings.SetLanguage("zh");await Task.Delay(100);AppSettings.SetLanguage("en");await Task.Delay(100);check(F<TextBox>(main,"outputDetail").Text.Contains("输入\n"),"Switching the main output pane language never translates raw program data");check(!File.Exists(Path.Combine(Engine.DataRoot,"scores.tsv")),"Tool-only workflow does not modify graded score history");log.Add("ALL VER1.3 WORKFLOW CHECKS PASSED");File.WriteAllLines(path,log.ToArray(),System.Text.Encoding.UTF8);main.Close();}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray(),System.Text.Encoding.UTF8);app.Shutdown(1);}};app.Run(main);}
}
